const logs = $input.first().json.logs;
const lines = logs.split(/\r?\n/).map(l => l.trim()).filter(Boolean);

const LINE_RE = /^(\S+) \S+ \S+ \[([^\]]+)\] "(\S+) (\S+) [^"]*" (\d{3}) (\S+)/;
const RULES = {
  SQLi: /(\bunion\b\s+(all\s+)?select\b|\bor\b\s+\d+=\d+|'\s*or\s*'|'\s*(--|#)|;\s*drop\s+table|\bsleep\s*\(|information_schema|\bselect\b.+\bfrom\b)/i,
  XSS: /(<\s*script|<\s*svg|<\s*img[^>]+on\w+\s*=|\bon(error|load|click|mouseover)\s*=|javascript:)/i,
  PathTraversal: /(\.\.\/|\.\.\\|\.\.%5c|\/etc\/passwd|\bwin\.ini|\bboot\.ini)/i
};

function decode(s) {
  let x = s;
  for (let i = 0; i < 3; i++) {
    try {
      const d = decodeURIComponent(x.replace(/\+/g, ' '));
      if (d === x) break;
      x = d;
    } catch (e) { break; }
  }
  return x;
}

const counts = { SQLi: 0, XSS: 0, PathTraversal: 0 };
const ipHits = {};
const suspicious = [];
let parsed = 0;

for (const line of lines) {
  const m = LINE_RE.exec(line);
  if (!m) continue;
  parsed++;
  const [, ip, , method, path, status] = m;
  const decoded = decode(path);
  const tags = Object.keys(RULES).filter(k => RULES[k].test(path) || RULES[k].test(decoded));
  if (!tags.length) continue;
  tags.forEach(t => counts[t]++);
  ipHits[ip] = (ipHits[ip] || 0) + 1;
  suspicious.push({ ip, method, status, request: path.slice(0, 200), tags });
}

const top_ips = Object.entries(ipHits)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 4)
  .map(([ip, hits]) => ({ ip, hits }));

const agent_prompt =
`Web access log scan results (regex pre-tagging).
Total lines: ${lines.length}, parsed: ${parsed}, suspicious: ${suspicious.length}
Regex counts: ${JSON.stringify(counts)}
Top offending IPs: ${JSON.stringify(top_ips)}
Suspicious requests (max 20):
${JSON.stringify(suspicious.slice(0, 20), null, 1)}

Tasks: (1) call the payload_decoder tool on at least one request per attack type, (2) confirm which attack types are REAL attacks vs false positives, (3) rate overall severity. Reply with the JSON only.`;

return [{ json: { total_lines: lines.length, parsed, suspicious_count: suspicious.length, counts, top_ips, suspicious, agent_prompt } }];

const raw = String(query || '');
let decoded = raw, layers = 0;
for (let i = 0; i < 3; i++) {
  try {
    const d = decodeURIComponent(decoded.replace(/\+/g, ' '));
    if (d === decoded) break;
    decoded = d; layers++;
  } catch (e) { break; }
}
const ind = [];
if (/union\s+(all\s+)?select|\bor\b\s+\d+=\d+|'\s*or\s*'|sleep\s*\(|information_schema|drop\s+table|'\s*(--|#)/i.test(decoded)) ind.push('SQLi');
if (/<\s*script|<\s*svg|onerror\s*=|onload\s*=|javascript:/i.test(decoded)) ind.push('XSS');
if (/\.\.\/|\.\.\\|\/etc\/passwd|win\.ini/i.test(decoded)) ind.push('PathTraversal');
const tools = /sqlmap|nikto|curl|python-requests|go-http/i.test(raw) ? 'automated-tool-signature' : 'none';
return JSON.stringify({
  decoded_payload: decoded.slice(0, 250),
  encoding_layers: layers,
  obfuscated: layers > 0,
  attack_indicators: ind,
  tool_signature: tools,
  severity_hint: ind.length === 0 ? 'Low' : (ind.includes('SQLi') || layers > 1) ? 'High' : 'Medium'
});

// S3 - Output validation: allowed values + max length
const t = $('Regex Tagger').first().json;
const attempt = $runIndex;                       // 0 = first try, 1 = retry
const raw = String($input.first().json.output ?? '');
const VERDICTS = ['Confirmed Attack', 'Suspicious', 'Benign'];
const SEVERITIES = ['Low', 'Medium', 'High', 'Critical'];
const TYPES = ['SQLi', 'XSS', 'PathTraversal'];
const errors = [];
let data = null;

try { data = JSON.parse(raw.replace(/```json|```/gi, '').trim()); }
catch (e) { errors.push('reply was not valid JSON'); }

if (data) {
  if (!VERDICTS.includes(data.verdict)) errors.push('verdict not in ' + VERDICTS.join('/'));
  if (!SEVERITIES.includes(data.severity)) errors.push('severity not in ' + SEVERITIES.join('/'));
  if (!Array.isArray(data.attack_types) || data.attack_types.length === 0 || !data.attack_types.every(x => TYPES.includes(x)))
    errors.push('attack_types must be a non-empty subset of ' + TYPES.join('/'));
  if (typeof data.summary !== 'string' || !data.summary.trim()) errors.push('summary missing');
  else {
    if (data.summary.length > 140) errors.push('summary longer than 140 chars');
    if (/[\r\n]/.test(data.summary)) errors.push('summary must be one line');
  }
}

const valid = errors.length === 0;
const agent_prompt = t.agent_prompt + (valid ? '' :
  `\n\nYour previous reply was REJECTED: ${errors.join('; ')}. Call the tool again if needed and return ONLY the corrected JSON.`);

return [{ json: { valid, attempt, errors, data, agent_prompt } }];

const d = $json.data;
const verdictSev = `${d.verdict} / ${d.severity}`;
const summary = d.summary.replace(/\s+/g, ' ').trim();
const t = $('Regex Tagger').first().json;
const ist = new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata', hour12: false }) + ' IST';
const first = `🟣 NGP-046 | exec #${$execution.id} | ${ist} | ${verdictSev} | ${summary}`;
const counts = Object.entries(t.counts).map(([k, v]) => `${k}: ${v}`).join(' | ');
const top = t.top_ips.map((x, i) => `${i + 1}. ${x.ip} - ${x.hits} hits`).join('\n');
const text = `${first}\n\nAttack counts: ${counts}\nTop 4 offending IPs:\n${top}`;
return [{ json: { text } }];

